/**
 * Swizzled from @theme-original/DocSidebarItem/Link to append an Enterprise
 * badge on items whose page frontmatter sets
 * `sidebar_custom_props: { enterprise: true }`.
 */
import React from 'react';
import clsx from 'clsx';
import { ThemeClassNames } from '@docusaurus/theme-common';
import { isActiveSidebarItem } from '@docusaurus/plugin-content-docs/client';
import Link from '@docusaurus/Link';
import isInternalUrl from '@docusaurus/isInternalUrl';
import IconExternalLink from '@theme/Icon/ExternalLink';
import { EnterpriseBadge } from '@site/src/components/ui/enterprise/enterpriseBadge';
import styles from './styles.module.css';

function LinkLabel({ label }) {
    return (
        <span title={label} className={styles.linkLabel}>
            {label}
        </span>
    );
}

export default function DocSidebarItemLink({
    item,
    onItemClick,
    activePath,
    level,
    index,
    ...props
}) {
    const { href, label, className, autoAddBaseUrl } = item;
    const isActive = isActiveSidebarItem(item, activePath);
    const isInternalLink = isInternalUrl(href);
    const isEnterprise = Boolean(item.customProps?.enterprise);
    return (
        <li
            className={clsx(
                ThemeClassNames.docs.docSidebarItemLink,
                ThemeClassNames.docs.docSidebarItemLinkLevel(level),
                'menu__list-item',
                className
            )}
            key={label}
        >
            <Link
                className={clsx(
                    'menu__link',
                    !isInternalLink && styles.menuExternalLink,
                    {
                        'menu__link--active': isActive,
                    }
                )}
                autoAddBaseUrl={autoAddBaseUrl}
                aria-current={isActive ? 'page' : undefined}
                to={href}
                {...(isInternalLink && {
                    onClick: onItemClick ? () => onItemClick(item) : undefined,
                })}
                {...props}
            >
                <LinkLabel label={label} />
                {isEnterprise && <EnterpriseBadge variant="sidebar" />}
                {!isInternalLink && <IconExternalLink />}
            </Link>
        </li>
    );
}
